mapper.sql:
FROM CSPD001TM A , CSPD201TM E -- 수출테이블 , CSPD202TM I -- 수입테이블 WHERE A.QLAS_CRPE_ENO = #{userId} AND A.AI_INPT_QLAS_ACVT_CD = '110' AND A.AI_INPT_ACVT_CD IN ('140', '160') AND A.ACTL_FX_REFNO = E.FX_ACNO(+) AND A.FX_REFNO_SRNO = E.XPO_CVRG_MK_SQ(+) AND A.ACTL_FX_REFNO = I.FX_ACNO(+) AND A.FX_REFNO_SRNO = I.TDOC_RCP_SRNO(+)
AND A.AI_INPT_QLAS_PROS_CD = #{inptPrcsCd}
AND A.ACTL_FX_REFNO LIKE '%' || UPPER(#{actlFxRefno}) || '%'
AND A.INPT_RCP_DT BETWEEN REPLACE(#{schSdate1}, '-', '') AND REPLACE(#{schEdate1}, '-', '')
)AA , CSPD112TI E , CSPD112TI F , CSPD112TI G , CSPD112TI H , CSPD112TI I , CSPD112TI J
WHERE E.AI_INPT_GRP_CD (+)= '150' AND E.AI_INPT_CMN_CD (+)= '3' AND F.AI_INPT_GRP_CD (+)= '280' AND F.AI_INPT_CMN_CD (+) = AA.AI_INPT_QLAS_PROS_CD AND G.AI_INPT_GRP_CD (+)= '290' AND G.AI_INPT_CMN_CD (+)= AA.AI_INPT_QLAS_ACVT_CD AND H.AI_INPT_GRP_CD (+)= '170' AND H.AI_INPT_CMN_CD (+)= AA.TOTALTEXT_AI_INPT_RST_CD AND I.AI_INPT_GRP_CD (+)= '170' AND I.AI_INPT_CMN_CD (+)= AA.ITM_INPT_AI_INPT_RST_CD AND J.AI_INPT_GRP_CD (+)= '170' AND J.AI_INPT_CMN_CD (+)= AA.SAFEWATCH_AI_INPT_RST_CD
AND AA.AI_INPT_CSNO = #{aiInptCsno}

mapper.select:
/* RevertTodoMapper.selectListTotCnt */ SELECT COUNT(*) totcnt FROM ( SELECT '3' AS INPT_ATMC_BIZ_DSCD , (--임시저장최종일시 SELECT NVL(MAX(LST_DB_CHG_DTM),'00000000000000000000') FROM( SELECT LST_DB_CHG_DTM AS LST_DB_CHG_DTM --심사처리시작시각 FROM CSPD005TH WHERE INPT_MST_SRNO = A.INPT_MST_SRNO AND AI_INPT_TPY_SAVE_YN = 'Y' AND AI_INPT_BIZ_DSCD = '3'
UNION ALL
SELECT LST_DB_CHG_DTM AS LST_DB_CHG_DTM --심사처리시작시각 FROM CSPD008TH WHERE INPT_MST_SRNO = A.INPT_MST_SRNO AND INPT_MST_SRNO IN (SELECT INPT_MST_SRNO FROM CSPD008TH WHERE INPT_MST_SRNO = A.INPT_MST_SRNO AND AI_INPT_BIZ_DSCD = '3' AND AI_INPT_ACVT_STS_CD = '51') ) ) AS SAVE_CHG_DTM , A.AI_INPT_QLAS_PROS_CD , A.AI_INPT_QLAS_ACVT_CD , NVL(E.XPBY_COL_CTR_CUCD, I.TDOC_RCP_CUCD) AS FC_CUNM , NVL(E.XPBY_COL_AM,I.TDOC_RCP_AM) AS AI_INPT_BUY_AM , NVL(E.CUS_KORL_NM,I.CUS_KORL_NM) AS AI_INPT_CUS_NM , NVL(E.CSNO, I.CSNO) AS AI_INPT_CSNO , A.TOTALTEXT_AI_INPT_RST_CD , A.ITM_INPT_AI_INPT_RST_CD , A.SAFEWATCH_AI_INPT_RST_CD , A.INPT_MST_SRNO , A.INPT_RCP_DT AS INPT_RCP_DT , A.ACTL_FX_REFNO , A.FX_REFNO_SRNO , A.AI_INPT_IMG_KEY_NO ,( SELECT MAX(FILT_DTCT_NO) KEEP( DENSE_RANK FIRST ORDER BY AI_INPT_PRG_SRNO DESC ) AS FILT_DTCT_NO FROM CSPD007TL WHERE INPT_MST_SRNO = A.INPT_MST_SRNO ) AS FILT_DTCT_NO , (SELECT MAX(X.AI_INPT_CMN_CD_NM) KEEP( DENSE_RANK FIRST ORDER BY H.AI_INPT_PRG_SRNO DESC) AS AI_INPT_CMN_CD_NM FROM CSPD008TH H , CSPD112TI X WHERE H.INPT_MST_SRNO = A.INPT_MST_SRNO AND H.AI_INPT_ACVT_STS_CD = '120' AND H.AI_INPT_BIZ_DSCD = '3' AND X.AI_INPT_GRP_CD(+) = '300' AND X.AI_INPT_CMN_CD(+) = H.AI_INPT_ACVT_STS_CD ) AS WRR_INFO , A.LST_DB_CHG_DTM AS MST_CHG_DTM
